function validate([grid]) {
  if (!Array.isArray(grid)) return 'grid must be a list of rows.';
  const n = grid.length;
  if (n < 2 || n > 50) return 'grid needs 2 to 50 rows.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'grid must be square (n rows of n values).';
    for (const h of row) {
      if (!Number.isInteger(h) || h < 0 || h > 100) return 'Each height is an integer from 0 to 100.';
    }
  }
  return null;
}

