function maxIncreaseKeepingSkyline(grid) {
  // Raise each building one unit at a time while its row and column tops stay the same.
  const n = grid.length;
  const city = grid.map(row => row.slice());
  const rowTop = (r) => Math.max(...city[r]);
  const colTop = (c) => Math.max(...city.map(row => row[c]));
  let added = 0;
  for (let r = 0; r < n; r++) {
    for (let c = 0; c < n; c++) {
      const beforeRow = rowTop(r);
      const beforeCol = colTop(c);
      for (;;) {
        city[r][c]++;
        if (rowTop(r) !== beforeRow || colTop(c) !== beforeCol) {
          city[r][c]--;
          break;
        }
        added++;
      }
    }
  }
  return added;
}

