function generate(rand, size) {
  const n = size === 'large' ? 50 : 2 + Math.floor(rand() * 4);
  const top = size === 'large' ? 100 : [0, 1, 3, 10][Math.floor(rand() * 4)];
  const grid = [];
  for (let r = 0; r < n; r++) {
    const row = [];
    for (let c = 0; c < n; c++) row.push(Math.floor(rand() * (top + 1)));
    grid.push(row);
  }
  return [grid];
}
